    'arabica-higashiyama': { name: '% Arabica Kyoto Higashiyama', area: 'Higashiyama', description: 'The very first % Arabica, right below the Yasaka Pagoda.', note: 'The Arashiyama shop is busier; the same latte is served here.' },
    hanamikoji: { name: 'Hanamikoji', area: 'Gion', description: 'Gion’s main street of stone paving and teahouse machiya, most atmospheric when the lanterns come on.', note: 'Photos are banned in the private side lanes (signs are posted); don’t chase geiko for photos.' },
