    lumine: { name: 'LUMINE 1 & LUMINE 2 Shinjuku', area: 'Shinjuku South Exit', description: 'Two linked department stores at the South Exit, with womenswear, menswear and homeware; LUMINE 2, 2F also has gelato pique.', note: 'About 5 minutes from LUMINE EST through the underground passage or via the South Exit.' },
    isetan: { name: 'Isetan Shinjuku Men’s', area: 'Shinjuku', description: 'A whole department store building for menswear, with the best range of Japanese designer labels (AURALEE, KAPITAL and more). A must for guys.', note: 'Next door to the Isetan main building; check the store directory for current counters.' },
