    takashimaya: { name: 'Shinjuku Takashimaya', area: 'Shinjuku South Exit', description: 'A big department store at the South Exit with luxury brands, men’s and women’s fashion and a basement food hall; easy tax-free counter.', note: 'About 3 minutes south of NEWoMan.' },
    yodobashi: { name: 'Yodobashi Camera Shinjuku West', area: 'Shinjuku West Exit', description: 'Shinjuku’s biggest electronics block, with cameras, headphones, games and models spread over several buildings. A favorite for guys.', note: 'Tax-free with a passport. About 10 minutes from the East Exit through the underground passage.' },
