    godzilla: { name: 'Kabukicho Godzilla', area: 'Kabukicho', description: 'The Godzilla head on top of the Shinjuku Toho Building, visible from the Kabukicho Ichibangai gate.', note: 'About 7 minutes on foot from the cat billboard.' },
